import 'package:cursor_bhai/core/database/app_database.dart';
import 'package:cursor_bhai/shared/domain/enums/account_type.dart';
import 'package:drift/drift.dart';

import '../../domain/entities/account_entity.dart';

class AccountMapper {
  static AccountEntity toDomain(Account row, {double currentBalance = 0}) {
    return AccountEntity(
      id: row.id,
      name: row.name,
      accountType: accountTypeFromStorage(row.accountType),
      currency: row.currency,
      initialBalance: row.initialBalance,
      isArchived: row.isArchived,
      createdAt: row.createdAt,
      updatedAt: row.updatedAt,
      currentBalance: currentBalance,
    );
  }

  static AccountsCompanion toInsertCompanion(AccountEntity entity) {
    return AccountsCompanion.insert(
      id: entity.id,
      name: entity.name,
      accountType: entity.accountType.storageKey,
      currency: entity.currency,
      initialBalance: entity.initialBalance,
      isArchived: Value(entity.isArchived),
      createdAt: entity.createdAt,
      updatedAt: entity.updatedAt,
    );
  }

  static Account toRow(AccountEntity entity) {
    return Account(
      id: entity.id,
      name: entity.name,
      accountType: entity.accountType.storageKey,
      currency: entity.currency,
      initialBalance: entity.initialBalance,
      isArchived: entity.isArchived,
      createdAt: entity.createdAt,
      updatedAt: entity.updatedAt,
    );
  }
}

