            IncomeVsExpenseChart(series: incomeExpenseSeries),
            const SizedBox(height: 16),
            _SectionHeader(title: 'Accounts', onSeeAll: () => context.go(AppRoutes.accounts)),
            Card(
              child: accounts.isEmpty
                  ? const ListTile(title: Text('No accounts — add one to start'))
                  : Column(
                      children: accounts.take(4).map((a) {
