// New widget: income vs expense grouped bar chart
import 'package:fl_chart/fl_chart.dart';
import 'package:flutter/material.dart';

import '../../../../core/utils/date_utils.dart';

class IncomeVsExpenseChart extends StatelessWidget {
  const IncomeVsExpenseChart({super.key, required this.series});

  final List<({DateTime month, double income, double expense})> series;

  @override
  Widget build(BuildContext context) {
    final scheme = Theme.of(context).colorScheme;
    final maxVal = series.isEmpty
        ? 1.0
        : series.map((s) => [s.income, s.expense].reduce((a, b) => a > b ? a : b)).reduce((a, b) => a > b ? a : b) * 1.2;

    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text('Income vs Expense', style: Theme.of(context).textTheme.titleMedium),
            const SizedBox(height: 12),
            SizedBox(
              height: 220,
              child: series.isEmpty
                  ? Center(child: Text('No data'))
                  : BarChart(
                      BarChartData(
                        maxY: maxVal <= 0 ? 1.0 : maxVal,
                        gridData: const FlGridData(show: false),
                        borderData: FlBorderData(show: false),
                        titlesData: FlTitlesData(
                          leftTitles: const AxisTitles(sideTitles: SideTitles(showTitles: false)),
                          topTitles: const AxisTitles(sideTitles: SideTitles(showTitles: false)),
                          rightTitles: const AxisTitles(sideTitles: SideTitles(showTitles: false)),
                          bottomTitles: AxisTitles(
                            sideTitles: SideTitles(
                              showTitles: true,
                              getTitlesWidget: (value, meta) {
                                final i = value.toInt();
                                if (i < 0 || i >= series.length) return const SizedBox.shrink();
                                final dt = series[i].month;
                                return Padding(
                                  padding: const EdgeInsets.only(top: 8),
                                  child: Text(AppDateUtils.formatMonthYear(dt), style: const TextStyle(fontSize: 11)),
                                );
                              },
                            ),
                          ),
                        ),
                        barGroups: List.generate(series.length, (i) {
                          final item = series[i];
                          return BarChartGroupData(
                            x: i,
                            barsSpace: 6,
                            barRods: [
                              BarChartRodData(
                                toY: item.income,
                                color: Colors.green,
                                width: 12,
                                borderRadius: const BorderRadius.vertical(top: Radius.circular(6)),
                              ),
                              BarChartRodData(
                                toY: item.expense,
                                color: scheme.error,
                                width: 12,
                                borderRadius: const BorderRadius.vertical(top: Radius.circular(6)),
                              ),
                            ],
                          );
                        }),
                      ),
                    ),
            ),
            const SizedBox(height: 8),
            Row(
              children: [
                Icon(Icons.circle, size: 10, color: Colors.green),
                const SizedBox(width: 6),
                const Text('Income'),
                const SizedBox(width: 12),
                Icon(Icons.circle, size: 10, color: scheme.error),
                const SizedBox(width: 6),
                const Text('Expense'),
              ],
            )
          ],
        ),
      ),
    );
  }
}

// New widget: monthly expense bar chart
import 'package:fl_chart/fl_chart.dart';
import 'package:flutter/material.dart';

import '../../../../core/utils/date_utils.dart';

class MonthlyExpenseChart extends StatelessWidget {
  const MonthlyExpenseChart({super.key, required this.series});

  final List<({DateTime month, double expense})> series;

  @override
  Widget build(BuildContext context) {
    final scheme = Theme.of(context).colorScheme;
    final maxY = (series.isEmpty ? 1.0 : series.map((s) => s.expense).reduce((a, b) => a > b ? a : b)) * 1.2;

    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text('Monthly expenses', style: Theme.of(context).textTheme.titleMedium),
            const SizedBox(height: 12),
            SizedBox(
              height: 200,
              child: series.isEmpty
                  ? Center(child: Text('No expense data'))
                  : BarChart(
                      BarChartData(
                        maxY: maxY <= 0 ? 1.0 : maxY,
                        gridData: const FlGridData(show: false),
                        borderData: FlBorderData(show: false),
                        titlesData: FlTitlesData(
                          leftTitles: const AxisTitles(sideTitles: SideTitles(showTitles: false)),
                          topTitles: const AxisTitles(sideTitles: SideTitles(showTitles: false)),
                          rightTitles: const AxisTitles(sideTitles: SideTitles(showTitles: false)),
                          bottomTitles: AxisTitles(
                            sideTitles: SideTitles(
                              showTitles: true,
                              getTitlesWidget: (value, meta) {
                                final i = value.toInt();
                                if (i < 0 || i >= series.length) return const SizedBox.shrink();
                                final dt = series[i].month;
                                return Padding(
                                  padding: const EdgeInsets.only(top: 8),
                                  child: Text(
                                    DateUtils.formatMonthYear(dt),
                                    style: const TextStyle(fontSize: 11),
                                  ),
                                );
                              },
                            ),
                          ),
                        ),
                        barGroups: List.generate(series.length, (i) {
                          final value = series[i].expense;
                          return BarChartGroupData(x: i, barRods: [
                            BarChartRodData(
                              toY: value,
                              color: scheme.error,
                              width: 18,
                              borderRadius: const BorderRadius.vertical(top: Radius.circular(6)),
                            ),
                          ]);
                        }),
                      ),
                    ),
            ),
          ],
        ),
      ),
    );
  }
}

// New widget: monthly expense bar chart
import 'package:fl_chart/fl_chart.dart';
import 'package:flutter/material.dart';

import '../../../../core/utils/date_utils.dart';

class MonthlyExpenseChart extends StatelessWidget {
  const MonthlyExpenseChart({super.key, required this.series});

  final List<({DateTime month, double expense})> series;

  @override
  Widget build(BuildContext context) {
    final scheme = Theme.of(context).colorScheme;
    final maxY = (series.isEmpty ? 1.0 : series.map((s) => s.expense).reduce((a, b) => a > b ? a : b)) * 1.2;

    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text('Monthly expenses', style: Theme.of(context).textTheme.titleMedium),
            const SizedBox(height: 12),
            SizedBox(
              height: 200,
              child: series.isEmpty
                  ? Center(child: Text('No expense data'))
                  : BarChart(
                      BarChartData(
                        maxY: maxY <= 0 ? 1.0 : maxY,
                        gridData: const FlGridData(show: false),
                        borderData: FlBorderData(show: false),
                        titlesData: FlTitlesData(
                          leftTitles: const AxisTitles(sideTitles: SideTitles(showTitles: false)),
                          topTitles: const AxisTitles(sideTitles: SideTitles(showTitles: false)),
                          rightTitles: const AxisTitles(sideTitles: SideTitles(showTitles: false)),
                          bottomTitles: AxisTitles(
                            sideTitles: SideTitles(
                              showTitles: true,
                              getTitlesWidget: (value, meta) {
                                final i = value.toInt();
                                if (i < 0 || i >= series.length) return const SizedBox.shrink();
                                final dt = series[i].month;
                                return Padding(
                                  padding: const EdgeInsets.only(top: 8),
                                  child: Text(
                                    AppDateUtils.formatMonthYear(dt),
                                    style: const TextStyle(fontSize: 11),
                                  ),
                                );
                              },
                            ),
                          ),
                        ),
                        barGroups: List.generate(series.length, (i) {
                          final value = series[i].expense;
                          return BarChartGroupData(x: i, barRods: [
                            BarChartRodData(
                              toY: value,
                              color: scheme.error,
                              width: 18,
                              borderRadius: const BorderRadius.vertical(top: Radius.circular(6)),
                            ),
                          ]);
                        }),
                      ),
                    ),
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import 'package:intl/intl.dart';
import '../../../shared/providers/loan_provider.dart';
import '../../../shared/models/loan.dart';

class LoansListScreen extends ConsumerWidget {
  const LoansListScreen({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final loans = ref.watch(loanProvider);
    final totalDebt = ref.watch(totalDebtProvider);
    final currencyFormat = NumberFormat.currency(symbol: 'Rs ', decimalDigits: 0);

    final totalMonthlyPayment = loans.fold(0.0, (sum, loan) => sum + loan.monthlyInstallment);

    return Scaffold(
      appBar: AppBar(title: const Text('Loans & Liabilities')),
      body: Column(
        children: [
          Container(
            margin: const EdgeInsets.all(16),
            padding: const EdgeInsets.all(24),
            decoration: BoxDecoration(
              gradient: const LinearGradient(
                colors: [Colors.orange, Colors.deepOrange],
              ),
              borderRadius: BorderRadius.circular(12),
            ),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text('Total Debt', style: TextStyle(color: Colors.white.withOpacity(0.9), fontSize: 14)),
                const SizedBox(height: 8),
                Text(currencyFormat.format(totalDebt), style: const TextStyle(color: Colors.white, fontSize: 32, fontWeight: FontWeight.bold)),
                const SizedBox(height: 8),
                Text('Monthly Payment: ${currencyFormat.format(totalMonthlyPayment)}', style: TextStyle(color: Colors.white.withOpacity(0.9))),
              ],
            ),
          ),
          Expanded(
            child: loans.isEmpty
                ? const Center(child: Text('No loans'))
                : ListView.builder(
                    padding: const EdgeInsets.symmetric(horizontal: 16),
                    itemCount: loans.length,
                    itemBuilder: (context, index) {
                      final loan = loans[index];
                      return Card(
                        margin: const EdgeInsets.only(bottom: 12),
                        child: InkWell(
                          onTap: () => context.push('/loans/${loan.id}'),
                          child: Padding(
                            padding: const EdgeInsets.all(16),
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Row(
                                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                                  children: [
                                    Text(loan.name, style: Theme.of(context).textTheme.titleMedium),
                                    Text(currencyFormat.format(loan.remainingAmount), style: const TextStyle(fontWeight: FontWeight.bold)),
                                  ],
                                ),
                                const SizedBox(height: 8),
                                Text('${loan.type.name.toUpperCase()} • ${loan.interestRate}% APR', style: Theme.of(context).textTheme.bodySmall),
                                const SizedBox(height: 12),
                                ClipRRect(
                                  borderRadius: BorderRadius.circular(4),
                                  child: LinearProgressIndicator(
                                    value: loan.progress / 100,
                                    minHeight: 8,
                                    backgroundColor: Colors.grey.shade200,
                                    valueColor: const AlwaysStoppedAnimation(Colors.green),
                                  ),
                                ),
                                const SizedBox(height: 4),
                                Text('${loan.progress.toStringAsFixed(0)}% paid', style: Theme.of(context).textTheme.bodySmall),
                              ],
                            ),
                          ),
                        ),
                      );
                    },
                  ),
          ),
        ],
      ),
    );
  }
}

