import '../../../accounts/presentation/providers/account_providers.dart';
import '../../../../shared/domain/enums/category_type.dart';
import '../../../categories/presentation/providers/category_providers.dart';
import '../../domain/entities/ledger_transaction.dart';
import '../../domain/services/transaction_ledger_service.dart';
import '../providers/transaction_providers.dart';
import 'package:cursor_bhai/features/dashboard/presentation/providers/dashboard_providers.dart';

class TransactionFormScreen extends ConsumerStatefulWidget {
  const TransactionFormScreen({
    super.key,
    this.transactionId,
    this.preselectedAccountId,
  });

  final String? transactionId;
  final String? preselectedAccountId;

  @override
  ConsumerState<TransactionFormScreen> createState() => _TransactionFormScreenState();
}

class _TransactionFormScreenState extends ConsumerState<TransactionFormScreen> {
  final _formKey = GlobalKey<FormState>();
  final _amountController = TextEditingController();
  final _notesController = TextEditingController();

  TransactionType _transactionType = TransactionType.expense;
  String? _sourceId;
  String? _destinationId;
  String? _categoryId;
  DateTime _transactionDate = DateTime.now();
  bool _loading = false;
  bool _initialized = false;

  bool get _isEdit => widget.transactionId != null;

  @override
  void dispose() {
    _amountController.dispose();
    _notesController.dispose();
    super.dispose();
  }

  void _applyTypeDefaults(List<AccountEntity> accounts) {
    switch (_transactionType) {
      case TransactionType.income:
      case TransactionType.dividend:
        _sourceId = null;
        _destinationId ??= widget.preselectedAccountId ?? _firstAccountId(accounts);
      case TransactionType.expense:
      case TransactionType.liabilityPayment:
        _destinationId = null;
        _sourceId ??= widget.preselectedAccountId ?? _firstAccountId(accounts);
      case TransactionType.transfer:
        _sourceId ??= widget.preselectedAccountId ?? _firstAccountId(accounts);
        _destinationId ??= _secondAccountId(accounts, _sourceId);
      case TransactionType.investmentFunding:
        _sourceId ??= _firstNonInvestmentAccount(accounts);
        _destinationId ??= _firstInvestmentAccount(accounts);
    }
  }

  String? _firstAccountId(List<AccountEntity> accounts) =>
      accounts.isNotEmpty ? accounts.first.id : null;

  String? _secondAccountId(List<AccountEntity> accounts, String? exclude) {
    final other = accounts.where((a) => a.id != exclude);
    return other.isNotEmpty ? other.first.id : null;
  }

  String? _firstInvestmentAccount(List<AccountEntity> accounts) {
    final list = accounts.where((a) => a.accountType == AccountType.investment);
    return list.isNotEmpty ? list.first.id : null;
  }

  String? _firstNonInvestmentAccount(List<AccountEntity> accounts) {
    final list = accounts.where((a) => a.accountType != AccountType.investment);
    return list.isNotEmpty ? list.first.id : null;
  }

  Future<void> _loadExisting() async {
    final tx = await ref.read(transactionRepositoryProvider).getById(widget.transactionId!);
    if (tx == null || !mounted) return;
    _amountController.text = tx.amount.toString();
    _notesController.text = tx.notes;
    setState(() {
      _transactionType = tx.transactionType;
      _sourceId = tx.sourceAccountId;
      _destinationId = tx.destinationAccountId;
      _categoryId = tx.categoryId;
      _transactionDate = tx.createdAt;
      _initialized = true;
    });
  }

  Future<void> _pickDate() async {
    final picked = await showDatePicker(
      context: context,
      initialDate: _transactionDate,
      firstDate: DateTime(2000),
      lastDate: DateTime.now().add(const Duration(days: 365)),
    );
    if (picked != null) {
      setState(() => _transactionDate = picked);
    }
  }

  Future<void> _save() async {
    if (!_formKey.currentState!.validate()) return;
    setState(() => _loading = true);

    final amount = double.parse(_amountController.text);
    final idGen = ref.read(idGeneratorProvider);
    final now = DateTime.now();

    final tx = LedgerTransaction(
      id: _isEdit ? widget.transactionId! : idGen.newId(),
      transactionType: _transactionType,
      sourceAccountId: _sourceId,
      destinationAccountId: _destinationId,
      categoryId: _categoryId,
      amount: amount,
      notes: _notesController.text.trim(),
      createdAt: _isEdit
          ? (await ref.read(transactionRepositoryProvider).getById(widget.transactionId!))!
              .createdAt
          : DateTime(
              _transactionDate.year,
              _transactionDate.month,
              _transactionDate.day,
              now.hour,
              now.minute,
            ),
      updatedAt: now,
    );

    try {
      if (_isEdit) {
        await ref.read(updateTransactionProvider)(tx);
      } else {
        await ref.read(createTransactionProvider)(tx);
      }
      // Refresh related providers so UI (accounts, net worth, lists) updates immediately
      ref.invalidate(transactionsListProvider);
      ref.invalidate(accountsListProvider);
      ref.invalidate(netWorthProvider);

      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text(_isEdit ? 'Transaction updated' : 'Transaction created')),
        );
        await Future.delayed(const Duration(milliseconds: 300));
        context.pop();
      }
    } on TransactionValidationException catch (e) {
      _showError(e.message);
    } catch (e) {
      _showError(e.toString());
    } finally {
      if (mounted) setState(() => _loading = false);
    }
  }

  void _showError(String message) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(message)));
  }

  List<AccountEntity> _destinationAccounts(List<AccountEntity> all) {
    if (_transactionType == TransactionType.investmentFunding) {
      return all.where((a) => a.accountType == AccountType.investment).toList();
    }
    return all;
  }

  List<AccountEntity> _sourceAccounts(List<AccountEntity> all) {
    if (_transactionType == TransactionType.investmentFunding) {
      return all.where((a) => a.accountType != AccountType.investment).toList();
    }
    return all;
  }

  @override
  Widget build(BuildContext context) {
    final accounts = ref.watch(accountsListProvider).valueOrNull ?? [];
    final categories = ref.watch(categoriesListProvider).valueOrNull ?? [];

    if (_isEdit && !_initialized) {
      _loadExisting();
      return const Scaffold(body: Center(child: CircularProgressIndicator()));
    }

    if (!_isEdit && !_initialized && accounts.isNotEmpty) {
      _applyTypeDefaults(accounts);
      _initialized = true;
    }

    final filteredCategories = categories.where((c) {
      return switch (_transactionType) {
        TransactionType.income => c.type == CategoryType.income,
        TransactionType.expense ||
        TransactionType.liabilityPayment =>
          c.type == CategoryType.expense,
        TransactionType.investmentFunding => c.type == CategoryType.investment,
        _ => true,
      };
    }).toList();

    return Scaffold(
      appBar: AppBar(title: Text(_isEdit ? 'Edit transaction' : 'New transaction')),
      body: Form(
        key: _formKey,
        child: ListView(
          padding: const EdgeInsets.all(16),
          children: [
            DropdownButtonFormField<TransactionType>(
              initialValue: _transactionType,
              decoration: const InputDecoration(labelText: 'Transaction type'),
              items: TransactionType.values
                  .map((t) => DropdownMenuItem(value: t, child: Text(t.label)))
                  .toList(),
              onChanged: (v) {
                setState(() {
                  _transactionType = v ?? _transactionType;
                  _applyTypeDefaults(accounts);
                });
              },
            ),
            const SizedBox(height: 16),
            if (_transactionType.requiresSource) ...[
              DropdownButtonFormField<String>(
                initialValue: _sourceId,
                decoration: const InputDecoration(labelText: 'Source account'),
                items: _sourceAccounts(accounts)
                    .map((a) => DropdownMenuItem(value: a.id, child: Text(a.name)))
                    .toList(),
                onChanged: (v) => setState(() => _sourceId = v),
                validator: (v) => v == null ? 'Select source account' : null,
              ),
              const SizedBox(height: 16),
            ],
            if (_transactionType.requiresDestination) ...[
              DropdownButtonFormField<String>(
                initialValue: _destinationId,
                decoration: InputDecoration(
                  labelText: _transactionType == TransactionType.investmentFunding
                      ? 'Investment funding account'
                      : 'Destination account',
                ),
                items: _destinationAccounts(accounts)
                    .map((a) => DropdownMenuItem(value: a.id, child: Text(a.name)))
                    .toList(),
                onChanged: (v) => setState(() => _destinationId = v),
                validator: (v) => v == null ? 'Select destination account' : null,
              ),
              const SizedBox(height: 16),
            ],
            if (filteredCategories.isNotEmpty)
              DropdownButtonFormField<String?>(
                initialValue: _categoryId,
                decoration: const InputDecoration(labelText: 'Category (optional)'),
                items: [
                  const DropdownMenuItem(value: null, child: Text('None')),
                  ...filteredCategories.map(
                    (c) => DropdownMenuItem(value: c.id, child: Text(c.name)),
                  ),
                ],
                onChanged: (v) => setState(() => _categoryId = v),
              ),
            const SizedBox(height: 16),
            TextFormField(
              controller: _amountController,
              keyboardType: const TextInputType.numberWithOptions(decimal: true),
              decoration: const InputDecoration(labelText: 'Amount (PKR)'),
              validator: (v) {
                final n = double.tryParse(v ?? '');
                if (n == null || n <= 0) return 'Enter a valid amount';
                return null;
              },
            ),
            const SizedBox(height: 16),
            ListTile(
              contentPadding: EdgeInsets.zero,
              title: const Text('Date'),
              subtitle: Text(AppDateUtils.formatDate(_transactionDate)),
              trailing: IconButton(
                icon: const Icon(Icons.calendar_today),
                onPressed: _isEdit ? null : _pickDate,
              ),
            ),
            const SizedBox(height: 8),
            TextFormField(
              controller: _notesController,
              decoration: const InputDecoration(labelText: 'Notes'),
              maxLines: 3,
            ),
            const SizedBox(height: 32),
            FilledButton(
              onPressed: _loading ? null : _save,
              child: _loading
                  ? const SizedBox(
                      height: 22,
                      width: 22,
                      child: CircularProgressIndicator(strokeWidth: 2),
                    )
                  : Text(_isEdit ? 'Save changes' : 'Save transaction'),
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import '../../../shared/models/transaction.dart';
import '../../../shared/providers/transaction_provider.dart';
import '../../../shared/providers/account_provider.dart';

class AddTransactionScreen extends ConsumerStatefulWidget {
  const AddTransactionScreen({super.key});

  @override
  ConsumerState<AddTransactionScreen> createState() => _AddTransactionScreenState();
}

class _AddTransactionScreenState extends ConsumerState<AddTransactionScreen> {
  final _formKey = GlobalKey<FormState>();
  final _amountController = TextEditingController();
  final _notesController = TextEditingController();

  TransactionType _selectedType = TransactionType.expense;
  String? _selectedCategory;
  String? _selectedAccountId;
  DateTime _selectedDate = DateTime.now();

  @override
  void dispose() {
    _amountController.dispose();
    _notesController.dispose();
    super.dispose();
  }

  List<String> _getCategories() {
    switch (_selectedType) {
      case TransactionType.income:
        return TransactionCategories.incomeCategories;
      case TransactionType.expense:
        return TransactionCategories.expenseCategories;
      case TransactionType.transfer:
        return ['Transfer'];
    }
  }

  void _handleSubmit() {
    if (_formKey.currentState!.validate() && _selectedAccountId != null && _selectedCategory != null) {
      final amount = double.parse(_amountController.text);

      // Check account balance for expense/transfer
      final account = ref.read(accountProvider.notifier).getAccountById(_selectedAccountId!);
      if (_selectedType == TransactionType.expense && account != null && amount > account.currentBalance) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Insufficient account balance for this expense')),
        );
        return;
      }

      final transaction = Transaction(
        type: _selectedType,
        amount: amount,
        category: _selectedCategory!,
        accountId: _selectedAccountId!,
        date: _selectedDate,
        notes: _notesController.text.isEmpty ? null : _notesController.text,
      );

      ref.read(transactionProvider.notifier).addTransaction(transaction);

      // Update account balances immediately
      if (_selectedType == TransactionType.income) {
        ref.read(accountProvider.notifier).updateBalance(_selectedAccountId!, transaction.amount);
      } else if (_selectedType == TransactionType.expense) {
        ref.read(accountProvider.notifier).updateBalance(_selectedAccountId!, -transaction.amount);
      }

      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Transaction added successfully')),
      );

      context.pop();
    }
  }

  @override
  Widget build(BuildContext context) {
    final accounts = ref.watch(accountProvider);

    return Scaffold(
      appBar: AppBar(
        title: const Text('Add Transaction'),
      ),
      body: Form(
        key: _formKey,
        child: ListView(
          padding: const EdgeInsets.all(16),
          children: [
            Text(
              'Transaction Type',
              style: Theme.of(context).textTheme.titleMedium,
            ),
            const SizedBox(height: 12),
            Row(
              children: [
                Expanded(
                  child: _TypeButton(
                    label: 'Income',
                    icon: Icons.arrow_downward,
                    color: Colors.green,
                    isSelected: _selectedType == TransactionType.income,
                    onTap: () {
                      setState(() {
                        _selectedType = TransactionType.income;
                        _selectedCategory = null;
                      });
                    },
                  ),
                ),
                const SizedBox(width: 12),
                Expanded(
                  child: _TypeButton(
                    label: 'Expense',
                    icon: Icons.arrow_upward,
                    color: Colors.red,
                    isSelected: _selectedType == TransactionType.expense,
                    onTap: () {
                      setState(() {
                        _selectedType = TransactionType.expense;
                        _selectedCategory = null;
                      });
                    },
                  ),
                ),
                const SizedBox(width: 12),
                Expanded(
                  child: _TypeButton(
                    label: 'Transfer',
                    icon: Icons.swap_horiz,
                    color: Colors.blue,
                    isSelected: _selectedType == TransactionType.transfer,
                    onTap: () {
                      setState(() {
                        _selectedType = TransactionType.transfer;
                        _selectedCategory = 'Transfer';
                      });
                    },
                  ),
                ),
              ],
            ),
            const SizedBox(height: 24),
            TextFormField(
              controller: _amountController,
              decoration: const InputDecoration(
                labelText: 'Amount',
                prefixText: 'Rs ',
                border: OutlineInputBorder(),
              ),
              keyboardType: TextInputType.number,
              validator: (value) {
                if (value == null || value.isEmpty) {
                  return 'Please enter amount';
                }
                if (double.tryParse(value) == null) {
                  return 'Invalid amount';
                }
                return null;
              },
            ),
            const SizedBox(height: 16),
            DropdownButtonFormField<String>(
              value: _selectedCategory,
              decoration: const InputDecoration(
                labelText: 'Category',
                border: OutlineInputBorder(),
              ),
              items: _getCategories().map((category) {
                return DropdownMenuItem(
                  value: category,
                  child: Text(category),
                );
              }).toList(),
              onChanged: (value) {
                setState(() => _selectedCategory = value);
              },
              validator: (value) => value == null ? 'Please select category' : null,
            ),
            const SizedBox(height: 16),
            DropdownButtonFormField<String>(
              value: _selectedAccountId,
              decoration: const InputDecoration(
                labelText: 'Account',
                border: OutlineInputBorder(),
              ),
              items: accounts.map((account) {
                return DropdownMenuItem(
                  value: account.id,
                  child: Text(account.name),
                );
              }).toList(),
              onChanged: (value) {
                setState(() => _selectedAccountId = value);
              },
              validator: (value) => value == null ? 'Please select account' : null,
            ),
            const SizedBox(height: 16),
            InkWell(
              onTap: () async {
                final date = await showDatePicker(
                  context: context,
                  initialDate: _selectedDate,
                  firstDate: DateTime(2020),
                  lastDate: DateTime.now(),
                );
                if (date != null) {
                  setState(() => _selectedDate = date);
                }
              },
              child: InputDecorator(
                decoration: const InputDecoration(
                  labelText: 'Date',
                  border: OutlineInputBorder(),
                ),
                child: Text(
                  '${_selectedDate.day}/${_selectedDate.month}/${_selectedDate.year}',
                ),
              ),
            ),
            const SizedBox(height: 16),
            TextFormField(
              controller: _notesController,
              decoration: const InputDecoration(
                labelText: 'Notes (Optional)',
                border: OutlineInputBorder(),
              ),
              maxLines: 3,
            ),
            const SizedBox(height: 24),
            Row(
              children: [
                Expanded(
                  child: OutlinedButton(
                    onPressed: () => context.pop(),
                    child: const Text('Cancel'),
                  ),
                ),
                const SizedBox(width: 16),
                Expanded(
                  child: FilledButton(
                    onPressed: _handleSubmit,
                    child: const Text('Add Transaction'),
                  ),
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }
}

class _TypeButton extends StatelessWidget {
  final String label;
  final IconData icon;
  final Color color;
  final bool isSelected;
  final VoidCallback onTap;

  const _TypeButton({
    required this.label,
    required this.icon,
    required this.color,
    required this.isSelected,
    required this.onTap,
  });

  @override
  Widget build(BuildContext context) {
    return InkWell(
      onTap: onTap,
      borderRadius: BorderRadius.circular(12),
      child: Container(
        padding: const EdgeInsets.all(16),
        decoration: BoxDecoration(
          color: isSelected ? color.withOpacity(0.1) : Colors.transparent,
          border: Border.all(
            color: isSelected ? color : Theme.of(context).dividerColor,
            width: isSelected ? 2 : 1,
          ),
          borderRadius: BorderRadius.circular(12),
        ),
        child: Column(
          children: [
            Icon(
              icon,
              color: isSelected ? color : Theme.of(context).colorScheme.onSurface.withOpacity(0.6),
            ),
            const SizedBox(height: 8),
            Text(
              label,
              style: TextStyle(
                color: isSelected ? color : null,
                fontWeight: isSelected ? FontWeight.bold : FontWeight.normal,
              ),
            ),
          ],
        ),
      ),
    );
  }
}

